  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> RunSummaryBuilder<'a, 'b, A> {
    let start = _fbb.start_table();
    RunSummaryBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<RunSummary<'a>> {
    let o = self.fbb_.end_table(self.start_);
    self.fbb_.required(o, RunSummary::VT_RUN_ID,"run_id");
    flatbuffers::WIPOffset::new(o.value())
  }
